ts=datetime.datetime.utcnow().strftime("%Y%m%dT%H%M%SZ")
p2=int(time.time())+86400
def get(url, fn):
    req=urllib.request.Request(url, headers={"User-Agent":UA,"Accept":"application/json"})
    for a in range(4):
        try:
            with urllib.request.urlopen(req, timeout=60) as r:
                b=r.read(); open(os.path.join(Y,fn),"wb").write(b); print(fn, r.status, len(b)); return b
        except Exception as e:
            print("ERR",fn,a,e); time.sleep(5*(a+1))
    return None
log=[]
for stmt,keys in (("income",INC),("balance",BAL),("cashflow",CF)):
    for freq in ("annual","quarterly","trailing"):
        if freq=="trailing" and stmt=="balance": continue
        types=[freq+k for k in keys]
        # chunk to keep URLs modest
        for i in range(0,len(types),60):
            chunk=types[i:i+60]
            q=urllib.parse.urlencode({"symbol":"ONGC.NS","type":",".join(chunk),"merge":"false","padTimeSeries":"true","period1":"493590046","period2":str(p2),"corsDomain":"finance.yahoo.com"})
            url="https://query1.finance.yahoo.com/ws/fundamentals-timeseries/v1/finance/timeseries/ONGC.NS?"+q
            fn=f"yahoo_fundamentals_ONGC.NS_{stmt}_{freq}_part{i//60+1}_{ts}.json"
            get(url,fn); log.append((fn,url)); time.sleep(2)
for sym in ("ONGC.NS","^NSEI"):
    s=sym.replace("^","")
    for rng,iv in (("max","1mo"),("10y","1d")):
        url=f"https://query1.finance.yahoo.com/v8/finance/chart/{urllib.parse.quote(sym)}?range={rng}&interval={iv}&events=div%2Csplit&includeAdjustedClose=true"
        fn=f"yahoo_chart_{s}_{rng}_{iv}_divsplit_{ts}.json"
        get(url,fn); log.append((fn,url)); time.sleep(2)
json.dump(log, open(os.path.join(Y,f"_fetch_log_{ts}.json"),"w"), indent=1)
